{
  "version": "2026-11",
  "levels": [
    {
      "id": "suggestive",
      "code": "suggestive",
      "title": {
        "fr": "Suggestif",
        "en": "Suggestive"
      },
      "description": {
        "fr": "Pour une décision donnée, l'agent suggère et l'humain décide. L'humain garde la main sur chaque action exécutoire.",
        "en": "For a given decision, the agent suggests and the human decides. The human keeps hold of every executing action."
      },
      "controls": {
        "fr": "Contrôle humain à 100%. Pas de kill switch nécessaire (l'humain est le kill switch). Logs des suggestions et des décisions humaines correspondantes.",
        "en": "100% human control. No kill switch needed (the human is the kill switch). Logs of suggestions and the matching human decisions."
      },
      "examples": {
        "fr": "Copilot d'écriture, recommandation produit non-personnalisée, assistant de rédaction d'emails.",
        "en": "Writing copilot, non-personalised product recommendation, email drafting assistant."
      }
    },
    {
      "id": "co_decision",
      "code": "co_decision",
      "title": {
        "fr": "Co-décision",
        "en": "Co-decision"
      },
      "description": {
        "fr": "Pour une décision donnée, l'agent propose une option argumentée et l'humain valide ou rejette. Chaque action exécutoire passe par une validation humaine, sur une option déjà cadrée.",
        "en": "For a given decision, the agent proposes a reasoned option and the human validates or rejects it. Every executing action goes through human validation, on an already framed option."
      },
      "controls": {
        "fr": "Validation humaine ≥ 95% des actions. Audit log de toutes les propositions (acceptées et rejetées). Métriques d'acceptation suivies (signal de drift).",
        "en": "Human validation ≥ 95% of actions. Audit log of all proposals (accepted and rejected). Acceptance metrics tracked (drift signal)."
      },
      "examples": {
        "fr": "Tri de tickets support avec proposition de réponse, suggestion de pricing avec validation manager, qualification de leads avec sign-off commercial.",
        "en": "Support ticket triage with proposed reply, pricing suggestion with manager sign-off, lead qualification with sales sign-off."
      }
    },
    {
      "id": "supervised_autonomous",
      "code": "supervised_autonomous",
      "title": {
        "fr": "Autonome supervisé",
        "en": "Supervised autonomous"
      },
      "description": {
        "fr": "Pour une décision donnée, l'agent décide et exécute dans un périmètre borné, sous supervision. Au-delà des seuils définis dans le mandat, il remonte obligatoirement la décision à un humain.",
        "en": "For a given decision, the agent decides and executes within a bounded perimeter, under supervision. Beyond the thresholds defined in the mandate, it must escalate the decision to a human."
      },
      "controls": {
        "fr": "Mandat formel obligatoire (cf. ACF-13). Seuils numériques et qualitatifs explicites. Kill switch actif et testé trimestriellement. Audit log structuré.",
        "en": "Mandatory formal mandate (cf. ACF-13). Explicit numeric and qualitative thresholds. Active kill switch tested quarterly. Structured audit log."
      },
      "examples": {
        "fr": "Agent de remboursement client jusqu'à 200€ sans validation, agent de réordonnancement stock dans la fourchette, agent de modération auto-correction.",
        "en": "Customer refund agent up to €200 without sign-off, stock reordering agent within a window, auto-correcting moderation agent."
      }
    },
    {
      "id": "autonomous",
      "code": "autonomous",
      "title": {
        "fr": "Autonome",
        "en": "Autonomous"
      },
      "description": {
        "fr": "Pour une décision donnée, l'agent décide et exécute sans validation humaine préalable, dans le périmètre du mandat. Le contrôle humain reste possible a posteriori et le dispositif d'arrêt reste actif.",
        "en": "For a given decision, the agent decides and executes without prior human validation, within the mandate's perimeter. Human control remains possible after the fact and the stop mechanism remains active."
      },
      "controls": {
        "fr": "Mandat formel approfondi, gouvernance renforcée (revue mensuelle minimum), kill switch multi-niveaux testé mensuellement, audit log à granularité décision, métriques de dérive en temps réel.",
        "en": "Deep formal mandate, reinforced governance (monthly review minimum), multi-level kill switch tested monthly, decision-grained audit log, real-time drift metrics."
      },
      "examples": {
        "fr": "Agent de trading algorithmique borné, agent de routage opérationnel critique, agent de gestion d'incident L1.",
        "en": "Bounded algorithmic trading agent, critical operational routing agent, L1 incident management agent."
      }
    }
  ]
}

{
  "title": { "fr": "DDAO : Delegated Decision Agent Officer", "en": "DDAO : Delegated Decision Agent Officer" },
  "expansion": "Delegated Decision Agent Officer",
  "definition": {
    "fr": "Rôle de gouvernance défini par ACF® qui agit comme gardien légal d'un ou plusieurs agents IA autonomes. Le DDAO valide le mandat de l'agent (cf. ACF-13), arbitre les escalades qui franchissent les seuils définis, autorise les évolutions du périmètre de décision et porte la responsabilité opérationnelle de l'agent vis-à-vis du COMEX et des régulateurs.",
    "en": "ACF®-defined governance role that acts as the legal guardian of one or more autonomous AI agents. The DDAO validates the agent mandate (cf. ACF-13), arbitrates escalations that cross defined thresholds, authorises decision-perimeter changes, and carries operational accountability for the agent vis-à-vis the executive committee and regulators."
  },
  "responsibilities": {
    "fr": "1. Approuver le mandat initial avant go-live.\n2. Arbitrer toute escalade hors-seuil dans les délais convenus.\n3. Réviser le mandat à fréquence prédéfinie (trimestre minimum pour criticité haute).\n4. Suspendre l'agent en cas de dérive observée.\n5. Reporter à l'instance de gouvernance compétente.\n6. Conserver la traçabilité des décisions humaines prises en réaction aux remontées de l'agent.",
    "en": "1. Approve the initial mandate before go-live.\n2. Arbitrate any out-of-threshold escalation within agreed deadlines.\n3. Review the mandate at predefined frequency (quarterly minimum for high criticality).\n4. Suspend the agent in case of observed drift.\n5. Report to the competent governance body.\n6. Retain traceability of human decisions taken in reaction to agent escalations."
  },
  "not_to_be_confused_with": {
    "fr": "Le DDAO n'est ni le DPO (qui couvre la protection des données personnelles), ni le RSSI (qui couvre la sécurité de l'information), ni le métier sponsor (qui porte le besoin business). Il est le rôle dédié à la gouvernance opérationnelle de l'autonomie agentique. Une même personne peut cumuler plusieurs rôles selon la taille de l'organisation, mais le rôle DDAO doit être identifié explicitement. Il ne se confond pas non plus avec le Chief Data & AI Officer (CDAIO), rôle de direction chargé de créer de la valeur avec l'IA et d'en piloter le passage à l'échelle. Le CDAIO accélère l'adoption, le DDAO répond des décisions qu'un agent prend seul. Les réunir dans la même main reviendrait à confier le frein à celui qu'on charge d'appuyer sur l'accélérateur, ce que le RGPD a écarté en rendant le DPO indépendant du responsable de traitement (art. 38). Le DDAO peut être rattaché au CDAIO à condition de conserver son indépendance de jugement.",
    "en": "The DDAO is neither the DPO (covers personal data protection), nor the CISO (covers information security), nor the business sponsor (carries the business need). It is the role dedicated to the operational governance of agentic autonomy. The same person may hold multiple roles in smaller organisations, but the DDAO role must be explicitly identified. It is also not the Chief Data & AI Officer (CDAIO), an executive role tasked with creating value from AI and driving its scaling. The CDAIO accelerates adoption, the DDAO answers for the decisions an agent makes on its own. Combining both in the same hands would hand the brake to the person tasked with pressing the accelerator, which the GDPR avoided by keeping the DPO independent from the data controller (art. 38). A DDAO may report to a CDAIO provided it retains independence of judgement."
  }
}

{
  "version": "1.0",
  "principles": [
    {
      "id": "P1",
      "code": "P1",
      "title": {
        "fr": "Souveraineté décisionnelle",
        "en": "Decision Sovereignty"
      },
      "summary": {
        "fr": "Les décisions stratégiques critiques ne sont jamais déléguées à des agents autonomes. L'organisation conserve la responsabilité ultime des décisions prises par ses agents, quel que soit le niveau d'autonomie qu'elle leur délègue.",
        "en": "Critical strategic decisions are never delegated to autonomous agents. The organisation keeps ultimate accountability for the decisions its agents take, whatever level of autonomy it delegates to them."
      },
      "doctrine": {
        "fr": "## Principe\n\nUn agent IA autonome ne déplace jamais la responsabilité décisionnelle hors de l'organisation. La délégation opérationnelle (l'agent agit) n'emporte pas délégation de responsabilité (l'organisation répond).\n\n## Implications opérationnelles\n\n- Tout agent est rattaché à un DDAO (Delegated Decision Agent Officer) identifié.\n- Tout périmètre de décision est borné par un mandat écrit (cf. ACF-13).\n- Tout franchissement de seuil critique remonte à un humain (cf. ACF-P6).",
        "en": "## Principle\n\nAn autonomous AI agent never moves decision accountability outside the organisation. Operational delegation (the agent acts) does not entail responsibility delegation (the organisation answers).\n\n## Operational implications\n\n- Every agent is attached to an identified DDAO (Delegated Decision Agent Officer).\n- Every decision perimeter is bounded by a written mandate (cf. ACF-13).\n- Every critical threshold breach escalates to a human (cf. ACF-P6)."
      },
      "related_fiches": [
        "ACF-01",
        "ACF-04",
        "ACF-13"
      ]
    },
    {
      "id": "P2",
      "code": "P2",
      "title": {
        "fr": "Gouvernance par conception",
        "en": "Governance by Design"
      },
      "summary": {
        "fr": "Les cadres de gouvernance sont définis avant le déploiement, pas après ; leur intensité est proportionnée à la criticité des décisions confiées à l'agent.",
        "en": "Governance frameworks are defined before deployment, not after, and their intensity is proportionate to the criticality of the decisions entrusted to the agent."
      },
      "doctrine": {
        "fr": "## Principe\n\nUn agent n'est pas mis en service avant que son cadre existe : constitution agentique (cf. ACF-04), mandat (cf. ACF-13), matrice de criticité (cf. ACF-03) et dispositif d'arrêt (cf. ACF-07). Ce cadre est proportionné : un agent qui ne fait que suggérer ne mérite pas le même appareil de contrôle qu'un agent qui décide seul. Surinvestir le contrôle sur une décision peu critique coûte sans bénéfice ; sous-investir sur une décision critique crée une exposition réglementaire et opérationnelle.\n\n## Implications opérationnelles\n\n- Dossier premier agent complet avant la mise en service (cf. ACF-08).\n- Sélection des contrôles depuis `ddao-controls-mapping` (niveau d'autonomie déléguée × risque → contrôles).\n- Revue annuelle de la calibration.",
        "en": "## Principle\n\nAn agent is not put into service before its framework exists: agentic constitution (cf. ACF-04), mandate (cf. ACF-13), criticality matrix (cf. ACF-03) and stop mechanism (cf. ACF-07). This framework is proportionate: an agent that only suggests does not warrant the same control apparatus as an agent that decides on its own. Over-investing controls on a low-criticality decision wastes resources; under-investing on a critical decision creates regulatory and operational exposure.\n\n## Operational implications\n\n- Complete first-agent dossier before go-live (cf. ACF-08).\n- Control selection from `ddao-controls-mapping` (delegated autonomy level × risk → controls).\n- Annual recalibration review."
      },
      "related_fiches": [
        "ACF-04",
        "ACF-13",
        "ACF-08",
        "ACF-03",
        "ACF-12",
        "ACF-P10"
      ]
    },
    {
      "id": "P3",
      "code": "P3",
      "title": {
        "fr": "Contrôle humain ultime",
        "en": "Ultimate Human Control"
      },
      "summary": {
        "fr": "Tout système agentique doit préserver la capacité d'intervention humaine : un dispositif de reprise activable à tout moment et calibré sur la criticité.",
        "en": "Every agentic system must preserve the ability for human intervention: a takeover mechanism that can be activated at any time and is calibrated to criticality."
      },
      "doctrine": {
        "fr": "## Principe\n\nL'autonomie d'un agent est un privilège conditionnel, jamais un droit acquis. À tout instant, un opérateur habilité doit pouvoir geler, infléchir ou révoquer l'agent. C'est l'expression opérationnelle de l'Article 14 de l'AI Act.\n\n## Implications opérationnelles\n\n- Kill switch documenté et testé (cf. ACF-07).\n- Seuils d'escalade explicites par criticité (cf. ACF-P6).\n- Tests réguliers de la reprise humaine (drill quarterly minimum sur criticité haute).",
        "en": "## Principle\n\nAn agent's autonomy is a conditional privilege, never a vested right. At any moment, an authorised operator must be able to freeze, redirect or revoke the agent. This is the operational expression of AI Act Article 14.\n\n## Operational implications\n\n- Documented and tested kill switch (cf. ACF-07).\n- Explicit escalation thresholds by criticality (cf. ACF-P6).\n- Regular human-takeover drills (at minimum quarterly for high criticality)."
      },
      "related_fiches": [
        "ACF-07",
        "ACF-P6",
        "ACF-P7"
      ]
    },
    {
      "id": "P4",
      "code": "P4",
      "title": {
        "fr": "Responsabilité traçable",
        "en": "Traceable Accountability"
      },
      "summary": {
        "fr": "Chaque action autonome doit pouvoir être auditée et attribuée : toute décision se reconstitue a posteriori en pointant la doctrine, les règles et les données qui l'ont produite ainsi que le responsable qui l'a autorisée.",
        "en": "Every autonomous action must be auditable and attributable: any decision can be reconstructed after the fact by pointing to the doctrine, rules and data that produced it, and to the person who authorised it."
      },
      "doctrine": {
        "fr": "## Principe\n\nUne décision agentique sans piste d'audit reconstituable est juridiquement indéfendable. ACF® impose qu'à chaque instant T, l'organisation puisse répondre à la question : « quelle version de la doctrine, quelles règles et quelles données ont produit cette décision ? »\n\n## Implications opérationnelles\n\n- Registre de décisions horodaté (cf. ACF-09).\n- Versionnement de la doctrine (`doctrine_version`, `doctrine_hash`, `doctrine_archive_url`).\n- Conservation des inputs et outputs structurés selon les durées légales applicables.",
        "en": "## Principle\n\nAn agentic decision without a reconstructible audit trail is legally indefensible. ACF® mandates that, at any time T, the organisation can answer the question: 'which doctrine version, which rules and which data produced this decision?'\n\n## Operational implications\n\n- Time-stamped decision register (cf. ACF-09).\n- Doctrine versioning (`doctrine_version`, `doctrine_hash`, `doctrine_archive_url`).\n- Retention of structured inputs and outputs for the applicable legal periods."
      },
      "related_fiches": [
        "ACF-09",
        "ACF-P14"
      ]
    }
  ]
}

[
  {
    "term": "ACF",
    "expansion": "Agentic Commerce Framework",
    "definition": "Open governance standard for autonomous AI agents, which sets 4 founding principles, 4 agent maturity levels (N0 to N3), 4 delegated autonomy levels set decision by decision, the DDAO role and 45 cards in 3 families: Decide (ACF-01 to ACF-20), Organise (ACF-O1 to ACF-O10) and Operate (ACF-P1 to ACF-P15).",
    "related_principles": [
      "P1",
      "P2",
      "P3",
      "P4"
    ],
    "related_fiches": [
      "ACF-01"
    ]
  },
  {
    "term": "DDAO",
    "expansion": "Delegated Decision Agent Officer",
    "definition": "ACF®-defined governance role acting as legal guardian of one or more autonomous AI agents. The DDAO approves the mandate, arbitrates out-of-threshold escalations and carries operational accountability for the agent. Not to be confused with the Chief Data & AI Officer (CDAIO), who creates value from AI: the DDAO is its accountability counterpart, independent as the DPO is from the data controller.",
    "related_principles": [
      "P3",
      "P2"
    ],
    "related_fiches": [
      "ACF-13"
    ]
  },
  {
    "term": "Agent Mandate",
    "definition": "Formal document bounding an autonomous agent's decision perimeter, escalation thresholds, technical safeguards and traceability obligations. Cf. ACF-13.",
    "related_principles": [
      "P1"
    ],
    "related_fiches": [
      "ACF-13",
      "ACF-04"
    ]
  },
  {
    "term": "Decision Sovereignty",
    "definition": "ACF® principle P1. The organisation retains ultimate accountability for the decisions taken by its AI agents. Operational delegation never entails responsibility delegation.",
    "related_principles": [
      "P1"
    ],
    "related_fiches": [
      "ACF-01"
    ]
  },
  {
    "term": "Traceable Accountability",
    "definition": "ACF® principle P4. Every automated decision must be reconstructible after the fact by pointing to the doctrine, rules and data that produced it.",
    "related_principles": [
      "P4"
    ],
    "related_fiches": [
      "ACF-09"
    ]
  },
  {
    "term": "Kill switch",
    "definition": "Human takeover mechanism allowing an agent to be frozen, redirected or revoked at any time. Multi-level: immediate suspension, deferred suspension, permanent revocation. Cf. ACF-07.",
    "related_principles": [
      "P3"
    ],
    "related_fiches": [
      "ACF-07",
      "ACF-P7"
    ]
  },
  {
    "term": "Delegated autonomy",
    "definition": "Level of power entrusted to an agent, set decision by decision on 4 levels: suggestive (the agent suggests, the human decides), co-decision (the agent proposes, the human validates), supervised autonomous (the agent decides within a bounded perimeter, under supervision) and autonomous (the agent decides on its own within its mandate). Never to be confused with agent maturity (N0 to N3).",
    "related_principles": [
      "P2"
    ],
    "related_fiches": [
      "ACF-02",
      "ACF-03",
      "ACF-13"
    ]
  },
  {
    "term": "Agent maturity (N0 to N3)",
    "definition": "Overall governance level of an agent, one value per agent: N0 classic automation, N1 assisted agent, N2 governed agent (it acts within a defined framework, under active supervision; the default target), N3 supervised autonomy. Maturity says nothing about the power delegated on a given decision, which is a matter of delegated autonomy.",
    "related_principles": [
      "P2",
      "P3"
    ],
    "related_fiches": [
      "ACF-05",
      "ACF-11"
    ]
  },
  {
    "term": "Criticality",
    "definition": "Score of an agentic decision: (impact × frequency × irreversibility) ÷ 10, each factor rated from 1 to 10 (card ACF-03). Below 15, the decision can go to the agent alone; from 15 to 25, it is taken under supervision; above 25, the final decision stays human, the agent preparing and proposing. Criticality bounds the acceptable delegation zone; it does not convert mechanically into an autonomy level.",
    "related_principles": [
      "P2"
    ],
    "related_fiches": [
      "ACF-03",
      "ACF-12"
    ]
  },
  {
    "term": "GPAI",
    "expansion": "General Purpose AI",
    "definition": "Category introduced by the AI Act (Art. 51-55) covering general-purpose foundation models. An agent relying on a GPAI inherits Article 53 obligations and: if the GPAI is systemic-risk: Article 55 obligations.",
    "related_principles": [],
    "related_fiches": [
      "ACF-12"
    ]
  },
  {
    "term": "Provider",
    "definition": "Under the AI Act, the entity that develops or has developed an AI system and places it on the market or puts it into service under its own name. The provider carries most of the obligations for high-risk systems.",
    "related_principles": [],
    "related_fiches": [
      "ACF-12"
    ]
  },
  {
    "term": "Deployer",
    "definition": "Under the AI Act, the entity using an AI system under its authority (other than for personal use). The deployer carries its own obligations (notably Articles 26 and 27 for high-risk systems).",
    "related_principles": [],
    "related_fiches": [
      "ACF-12"
    ]
  },
  {
    "term": "Controller",
    "definition": "Under the GDPR, the entity determining the purposes and means of the processing of personal data. An autonomous AI agent does not erase the controller qualification: it operationalises it.",
    "related_principles": [],
    "related_fiches": [
      "ACF-P14"
    ]
  },
  {
    "term": "DPIA",
    "expansion": "Data Protection Impact Assessment",
    "definition": "Impact assessment required by Article 35 GDPR for processing operations at high risk to rights and freedoms. Often mandatory for high-risk AI agents.",
    "related_principles": [
      "P4"
    ],
    "related_fiches": [
      "ACF-12"
    ]
  },
  {
    "term": "Decision Register",
    "definition": "Time-stamped log recording every decision taken by an autonomous agent, with structured inputs, output, applied doctrine version and rationale. Each entry is signed, so any alteration becomes detectable. Cf. ACF-09.",
    "related_principles": [
      "P4"
    ],
    "related_fiches": [
      "ACF-09"
    ]
  },
  {
    "term": "Article 49",
    "definition": "AI Act article creating a public register of high-risk AI systems. The deployer or provider must register the system before putting it into service. The registration content must be consistent with the internal decision register.",
    "related_principles": [],
    "related_fiches": [
      "ACF-09",
      "ACF-12"
    ]
  }
]

[
  {
    "term": "ACF",
    "expansion": "Agentic Commerce Framework",
    "definition": "Standard ouvert de gouvernance des agents IA autonomes, qui pose 4 principes fondateurs, 4 niveaux de maturité de l'agent (N0 à N3), 4 niveaux d'autonomie déléguée fixés décision par décision, le rôle DDAO et 45 fiches réparties en 3 familles : Décider (ACF-01 à ACF-20), Organiser (ACF-O1 à ACF-O10) et Opérer (ACF-P1 à ACF-P15).",
    "related_principles": [
      "P1",
      "P2",
      "P3",
      "P4"
    ],
    "related_fiches": [
      "ACF-01"
    ]
  },
  {
    "term": "DDAO",
    "expansion": "Delegated Decision Agent Officer",
    "definition": "Rôle de gouvernance défini par ACF® qui agit comme gardien légal d'un ou plusieurs agents IA autonomes. Le DDAO valide le mandat, arbitre les escalades hors-seuils et porte la responsabilité opérationnelle de l'agent. À ne pas confondre avec le Chief Data & AI Officer (CDAIO), qui crée de la valeur avec l'IA : le DDAO en est le contrepoids de responsabilité, indépendant comme l'est le DPO du responsable de traitement.",
    "related_principles": [
      "P3",
      "P2"
    ],
    "related_fiches": [
      "ACF-13"
    ]
  },
  {
    "term": "Mandat d'agent",
    "definition": "Document formel qui borne le périmètre de décision d'un agent autonome, ses seuils d'escalade, ses garde-fous techniques et ses obligations de traçabilité. Cf. ACF-13.",
    "related_principles": [
      "P1"
    ],
    "related_fiches": [
      "ACF-13",
      "ACF-04"
    ]
  },
  {
    "term": "Souveraineté décisionnelle",
    "definition": "Principe ACF® P1. L'organisation conserve la responsabilité ultime des décisions prises par ses agents IA. La délégation opérationnelle n'emporte jamais délégation de responsabilité.",
    "related_principles": [
      "P1"
    ],
    "related_fiches": [
      "ACF-01"
    ]
  },
  {
    "term": "Responsabilité traçable",
    "definition": "Principe ACF® P4. Toute décision automatisée doit pouvoir être reconstituée a posteriori en pointant la doctrine, les règles et les données qui l'ont produite.",
    "related_principles": [
      "P4"
    ],
    "related_fiches": [
      "ACF-09"
    ]
  },
  {
    "term": "Kill switch",
    "definition": "Dispositif de reprise humaine permettant de geler, infléchir ou révoquer un agent à tout instant. Multi-niveaux : suspension immédiate, suspension différée, révocation définitive. Cf. ACF-07.",
    "related_principles": [
      "P3"
    ],
    "related_fiches": [
      "ACF-07",
      "ACF-P7"
    ]
  },
  {
    "term": "Autonomie déléguée",
    "definition": "Niveau de pouvoir confié à un agent, fixé décision par décision sur 4 niveaux : suggestif (l'agent suggère, l'humain décide), co-décision (l'agent propose, l'humain valide), autonome supervisé (l'agent décide dans un périmètre borné, sous supervision) et autonome (l'agent décide seul dans les limites de son mandat). Ne se confond jamais avec la maturité de l'agent (N0 à N3).",
    "related_principles": [
      "P2"
    ],
    "related_fiches": [
      "ACF-02",
      "ACF-03",
      "ACF-13"
    ]
  },
  {
    "term": "Maturité de l'agent (N0 à N3)",
    "definition": "Niveau global de gouvernance d'un agent, une seule valeur par agent : N0 automatisation classique, N1 agent assisté, N2 agent gouverné (il agit dans un cadre défini, sous supervision active ; c'est la cible par défaut), N3 autonomie supervisée. La maturité ne dit rien du pouvoir délégué sur une décision donnée, qui relève de l'autonomie déléguée.",
    "related_principles": [
      "P2",
      "P3"
    ],
    "related_fiches": [
      "ACF-05",
      "ACF-11"
    ]
  },
  {
    "term": "Criticité",
    "definition": "Note d'une décision agentique : (impact × fréquence × irréversibilité) ÷ 10, chaque facteur noté de 1 à 10 (fiche ACF-03). Sous 15, la décision peut revenir à l'agent seul ; de 15 à 25, elle se prend sous supervision ; au-dessus de 25, la décision finale reste humaine, l'agent préparant et proposant. La criticité borne la zone de délégation acceptable, elle ne se convertit pas mécaniquement en niveau d'autonomie.",
    "related_principles": [
      "P2"
    ],
    "related_fiches": [
      "ACF-03",
      "ACF-12"
    ]
  },
  {
    "term": "GPAI",
    "expansion": "General Purpose AI",
    "definition": "Catégorie introduite par l'AI Act (Art. 51-55) qui désigne les modèles de fondation à usage général. Un agent qui s'appuie sur un GPAI hérite d'obligations Article 53 et: si le GPAI est à risque systémique: Article 55.",
    "related_principles": [],
    "related_fiches": [
      "ACF-12"
    ]
  },
  {
    "term": "Provider",
    "definition": "Au sens de l'AI Act, l'entité qui développe ou fait développer un système d'IA et le met sur le marché ou en service sous son nom. Le provider porte la majorité des obligations de l'AI Act sur les systèmes à haut risque.",
    "related_principles": [],
    "related_fiches": [
      "ACF-12"
    ]
  },
  {
    "term": "Deployer",
    "definition": "Au sens de l'AI Act, l'entité qui utilise un système d'IA sous son autorité (autre qu'à titre personnel). Le deployer porte des obligations propres (notamment Article 26 et 27 pour les systèmes à haut risque).",
    "related_principles": [],
    "related_fiches": [
      "ACF-12"
    ]
  },
  {
    "term": "Controller",
    "definition": "Au sens du RGPD, l'entité qui détermine les finalités et les moyens du traitement de données personnelles. Un agent IA autonome n'efface pas la qualification de controller: il l'opérationnalise.",
    "related_principles": [],
    "related_fiches": [
      "ACF-P14"
    ]
  },
  {
    "term": "DPIA",
    "expansion": "Data Protection Impact Assessment",
    "definition": "Évaluation d'impact prévue par l'Article 35 du RGPD pour les traitements à risque élevé pour les droits et libertés. Souvent obligatoire pour les agents IA à haut risque.",
    "related_principles": [
      "P4"
    ],
    "related_fiches": [
      "ACF-12"
    ]
  },
  {
    "term": "Registre des décisions",
    "definition": "Journal horodaté qui consigne chaque décision prise par un agent autonome, avec les entrées structurées, la sortie, la version de doctrine appliquée et la justification. Chaque entrée est signée de sorte que toute altération devient détectable. Cf. ACF-09.",
    "related_principles": [
      "P4"
    ],
    "related_fiches": [
      "ACF-09"
    ]
  },
  {
    "term": "Article 49",
    "definition": "Article de l'AI Act qui crée un registre public des systèmes IA à haut risque. Le deployer ou le provider doit y inscrire le système avant mise en service. Le contenu de l'inscription doit être cohérent avec le registre interne de décisions.",
    "related_principles": [],
    "related_fiches": [
      "ACF-09",
      "ACF-12"
    ]
  }
]

{
  "_meta": {
    "schema": "acf-regulation-articles/1.0",
    "regulatory_snapshot": "AI Act (Reg. (EU) 2024/1689) incl. Digital Omnibus deferrals · GDPR (Reg. (EU) 2016/679) · DORA (Reg. (EU) 2022/2554) · NIS2 (Dir. (EU) 2022/2555) · ISO/IEC 42001:2023: as interpreted on 2026-06-07",
    "nature": "ACF governance mapping. The `text` field is a faithful short summary of each official provision (not its verbatim legal text); always read the cited instrument. The `mapping` and `operational_note` are ACF doctrine. Preliminary qualification, not legal advice: requires_human_review.",
    "fiche_mapping_caveat": "Fiche / principle references reflect ACF v1.0 doctrine."
  },
  "regulations": {
    "ai-act": {
      "label": {
        "fr": "AI Act : Règlement (UE) 2024/1689",
        "en": "AI Act: Regulation (EU) 2024/1689"
      },
      "articles": {
        "9": {
          "title": {
            "fr": "Système de gestion des risques (IA à haut risque)",
            "en": "Risk management system (high-risk AI)"
          },
          "text": {
            "fr": "Les fournisseurs de systèmes d'IA à haut risque établissent, mettent en œuvre, documentent et maintiennent un système de gestion des risques itératif tout au long du cycle de vie. Cf. Règlement (UE) 2024/1689, art. 9.",
            "en": "Providers of high-risk AI systems shall establish, implement, document and maintain a risk management system running iteratively across the lifecycle. See Regulation (EU) 2024/1689, Article 9."
          },
          "mapping": {
            "principles": ["P4", "P2"],
            "fiches": ["ACF-03", "ACF-12"],
            "operational_note": {
              "fr": "ACF opérationnalise l'art. 9 via ACF-03 (matrice de criticité) + ACF-12 (évaluation du risque), borné par P2 (gouvernance proportionnelle).",
              "en": "ACF operationalises Art. 9 via ACF-03 (criticality matrix) + ACF-12 (risk assessment), bounded by P2 (governance by design)."
            }
          },
          "source": "Regulation (EU) 2024/1689, Article 9",
          "applicable_date": "2027-12-02"
        },
        "10": {
          "title": {
            "fr": "Données et gouvernance des données (IA à haut risque)",
            "en": "Data and data governance (high-risk AI)"
          },
          "text": {
            "fr": "Les jeux de données d'entraînement, de validation et de test sont soumis à des pratiques de gouvernance appropriées à la finalité visée (pertinence, représentativité, biais). Cf. Règlement (UE) 2024/1689, art. 10.",
            "en": "Training, validation and testing data sets shall be subject to data governance practices appropriate to the intended purpose (relevance, representativeness, bias). See Regulation (EU) 2024/1689, Article 10."
          },
          "mapping": {
            "principles": ["P4"],
            "fiches": ["ACF-09", "ACF-P14"],
            "operational_note": {
              "fr": "ACF opérationnalise l'art. 10 via ACF-09 (registre des décisions) + ACF-P14 (politique de rétention).",
              "en": "ACF operationalises Art. 10 via ACF-09 (decision register) + ACF-P14 (retention policy)."
            }
          },
          "source": "Regulation (EU) 2024/1689, Article 10",
          "applicable_date": "2027-12-02"
        },
        "12": {
          "title": {
            "fr": "Enregistrement (journalisation)",
            "en": "Record-keeping (logging)"
          },
          "text": {
            "fr": "Les systèmes d'IA à haut risque permettent l'enregistrement automatique des événements (logs) sur leur durée de vie, pour assurer la traçabilité du fonctionnement. Cf. Règlement (UE) 2024/1689, art. 12.",
            "en": "High-risk AI systems shall technically allow for the automatic recording of events (logs) over their lifetime, ensuring traceability of functioning. See Regulation (EU) 2024/1689, Article 12."
          },
          "mapping": {
            "principles": ["P4"],
            "fiches": ["ACF-09"],
            "operational_note": {
              "fr": "ACF opérationnalise l'art. 12 via ACF-09 (registre horodaté des décisions) + ACF-09 (piste d'audit reconstituable), expression directe de P4.",
              "en": "ACF operationalises Art. 12 via ACF-09 (time-stamped decision register) + ACF-09 (reconstructible audit trail), a direct expression of P4."
            }
          },
          "source": "Regulation (EU) 2024/1689, Article 12",
          "applicable_date": "2027-12-02"
        },
        "13": {
          "title": {
            "fr": "Transparence et information des déployeurs",
            "en": "Transparency and provision of information to deployers"
          },
          "text": {
            "fr": "Les systèmes d'IA à haut risque sont conçus pour être suffisamment transparents et accompagnés d'une notice d'utilisation permettant aux déployeurs d'interpréter et d'utiliser correctement les sorties. Cf. Règlement (UE) 2024/1689, art. 13.",
            "en": "High-risk AI systems shall be designed to be sufficiently transparent and accompanied by instructions for use enabling deployers to interpret and use the output correctly. See Regulation (EU) 2024/1689, Article 13."
          },
          "mapping": {
            "principles": ["P3"],
            "fiches": ["ACF-05", "ACF-13"],
            "operational_note": {
              "fr": "ACF opérationnalise l'art. 13 via ACF-05 (fiche agent documentée) + ACF-13 (mandat écrit précisant périmètre et limites).",
              "en": "ACF operationalises Art. 13 via ACF-05 (documented agent card) + ACF-13 (written mandate stating perimeter and limits)."
            }
          },
          "source": "Regulation (EU) 2024/1689, Article 13",
          "applicable_date": "2027-12-02"
        },
        "14": {
          "title": {
            "fr": "Contrôle humain (IA à haut risque)",
            "en": "Human oversight (high-risk AI)"
          },
          "text": {
            "fr": "Les systèmes d'IA à haut risque sont conçus pour pouvoir être effectivement supervisés par des personnes physiques pendant leur utilisation, y compris par des mesures d'arrêt. Cf. Règlement (UE) 2024/1689, art. 14.",
            "en": "High-risk AI systems shall be designed so they can be effectively overseen by natural persons during use, including through stop mechanisms. See Regulation (EU) 2024/1689, Article 14."
          },
          "mapping": {
            "principles": ["P3"],
            "fiches": ["ACF-07", "ACF-P6", "ACF-P7"],
            "operational_note": {
              "fr": "ACF opérationnalise l'art. 14 via P3 (contrôle humain ultime), ACF-07 (kill switch), ACF-P6 (seuils d'escalade), ACF-P7 (drills de reprise humaine).",
              "en": "ACF operationalises Art. 14 via P3 (ultimate human control), ACF-07 (kill switch), ACF-P6 (escalation thresholds), ACF-P7 (human-takeover drills)."
            }
          },
          "source": "Regulation (EU) 2024/1689, Article 14",
          "applicable_date": "2027-12-02"
        }
      }
    },
    "gdpr": {
      "label": {
        "fr": "RGPD : Règlement (UE) 2016/679",
        "en": "GDPR: Regulation (EU) 2016/679"
      },
      "articles": {
        "5": {
          "title": {
            "fr": "Principes relatifs au traitement",
            "en": "Principles relating to processing"
          },
          "text": {
            "fr": "Le traitement des données personnelles obéit aux principes de licéité, limitation des finalités, minimisation, exactitude, limitation de conservation, intégrité/confidentialité et responsabilité (accountability). Cf. Règlement (UE) 2016/679, art. 5.",
            "en": "Processing of personal data must follow the principles of lawfulness, purpose limitation, data minimisation, accuracy, storage limitation, integrity/confidentiality and accountability. See Regulation (EU) 2016/679, Article 5."
          },
          "mapping": {
            "principles": ["P1", "P4"],
            "fiches": ["ACF-04", "ACF-P14"],
            "operational_note": {
              "fr": "ACF opérationnalise l'art. 5 via ACF-04 (constitution interdisant les accès PII hors finalité) + ACF-P14 (limitation de conservation).",
              "en": "ACF operationalises Art. 5 via ACF-04 (constitution forbidding non-purposeful PII access) + ACF-P14 (storage limitation)."
            }
          },
          "source": "Regulation (EU) 2016/679, Article 5"
        },
        "22": {
          "title": {
            "fr": "Décision individuelle automatisée",
            "en": "Automated individual decision-making"
          },
          "text": {
            "fr": "La personne concernée a le droit de ne pas faire l'objet d'une décision fondée exclusivement sur un traitement automatisé produisant des effets juridiques ou l'affectant de manière significative, sauf exceptions encadrées (consentement, contrat, loi) avec garanties. Cf. Règlement (UE) 2016/679, art. 22.",
            "en": "The data subject has the right not to be subject to a decision based solely on automated processing producing legal or similarly significant effects, save framed exceptions (consent, contract, law) with safeguards. See Regulation (EU) 2016/679, Article 22."
          },
          "mapping": {
            "principles": ["P1", "P3"],
            "fiches": ["ACF-P6", "ACF-13"],
            "operational_note": {
              "fr": "Pilier direct du contrôle humain : ACF borne l'autonomie (mandat ACF-13) et impose la remontée humaine (ACF-P6) dès qu'une décision agentique produit un effet significatif sur une personne.",
              "en": "A direct human-control pillar: ACF bounds autonomy (ACF-13 mandate) and forces human escalation (ACF-P6) whenever an agentic decision produces a significant effect on a person."
            }
          },
          "source": "Regulation (EU) 2016/679, Article 22"
        },
        "25": {
          "title": {
            "fr": "Protection des données dès la conception et par défaut",
            "en": "Data protection by design and by default"
          },
          "text": {
            "fr": "Le responsable du traitement met en œuvre des mesures techniques et organisationnelles appropriées pour garantir la protection des données dès la conception et par défaut. Cf. Règlement (UE) 2016/679, art. 25.",
            "en": "The controller shall implement appropriate technical and organisational measures to ensure data protection by design and by default. See Regulation (EU) 2016/679, Article 25."
          },
          "mapping": {
            "principles": ["P4"],
            "fiches": ["ACF-04", "ACF-P14"],
            "operational_note": {
              "fr": "ACF opérationnalise l'art. 25 via ACF-04 (constitution) + ACF-P14 (politique de rétention).",
              "en": "ACF operationalises Art. 25 via ACF-04 (constitution) + ACF-P14 (retention policy)."
            }
          },
          "source": "Regulation (EU) 2016/679, Article 25"
        },
        "30": {
          "title": {
            "fr": "Registre des activités de traitement",
            "en": "Records of processing activities"
          },
          "text": {
            "fr": "Le responsable et le sous-traitant tiennent un registre des activités de traitement relevant de leur responsabilité. Cf. Règlement (UE) 2016/679, art. 30.",
            "en": "The controller and processor shall maintain a record of processing activities under their responsibility. See Regulation (EU) 2016/679, Article 30."
          },
          "mapping": {
            "principles": ["P4"],
            "fiches": ["ACF-09"],
            "operational_note": {
              "fr": "Le registre des décisions ACF-09 alimente et recoupe le registre RGPD art. 30 pour les traitements agentiques.",
              "en": "The ACF-09 decision register feeds and cross-checks the GDPR Art. 30 record for agentic processing."
            }
          },
          "source": "Regulation (EU) 2016/679, Article 30"
        },
        "35": {
          "title": {
            "fr": "Analyse d'impact relative à la protection des données (AIPD/DPIA)",
            "en": "Data protection impact assessment (DPIA)"
          },
          "text": {
            "fr": "Lorsqu'un traitement est susceptible d'engendrer un risque élevé pour les droits et libertés, le responsable effectue une analyse d'impact (AIPD). Cf. Règlement (UE) 2016/679, art. 35.",
            "en": "Where processing is likely to result in a high risk to the rights and freedoms of natural persons, the controller shall carry out a DPIA. See Regulation (EU) 2016/679, Article 35."
          },
          "mapping": {
            "principles": ["P4"],
            "fiches": ["ACF-12"],
            "operational_note": {
              "fr": "ACF-12 (évaluation du risque) alimente le gabarit AIPD/DPIA.",
              "en": "ACF-12 (risk assessment) feeds the DPIA template."
            }
          },
          "source": "Regulation (EU) 2016/679, Article 35"
        }
      }
    },
    "dora": {
      "label": {
        "fr": "DORA : Règlement (UE) 2022/2554 (applicable depuis le 2025-01-17)",
        "en": "DORA: Regulation (EU) 2022/2554 (applicable since 2025-01-17)"
      },
      "articles": {
        "5": {
          "title": {
            "fr": "Gouvernance et organisation (cadre de gestion du risque TIC)",
            "en": "Governance and organisation (ICT risk management)"
          },
          "text": {
            "fr": "L'organe de direction de l'entité financière définit, approuve et supervise le cadre de gestion du risque lié aux TIC et en porte la responsabilité finale. Cf. Règlement (UE) 2022/2554, art. 5.",
            "en": "The management body of the financial entity defines, approves and oversees the ICT risk management framework and bears ultimate responsibility for it. See Regulation (EU) 2022/2554, Article 5."
          },
          "mapping": {
            "principles": ["P1"],
            "fiches": ["ACF-01", "ACF-13"],
            "operational_note": {
              "fr": "Convergent avec P1 : la responsabilité ultime reste à l'organe de direction. ACF rattache chaque agent qui décide seul à un DDAO et un mandat (ACF-13).",
              "en": "Converges with P1: ultimate responsibility stays with the management body. ACF attaches every agent that decides on its own to a DDAO and a mandate (ACF-13)."
            }
          },
          "source": "Regulation (EU) 2022/2554, Article 5",
          "applicable_date": "2025-01-17"
        },
        "6": {
          "title": {
            "fr": "Cadre de gestion du risque lié aux TIC",
            "en": "ICT risk management framework"
          },
          "text": {
            "fr": "L'entité financière dispose d'un cadre solide, complet et documenté de gestion du risque TIC, intégré à sa gestion globale des risques. Cf. Règlement (UE) 2022/2554, art. 6.",
            "en": "The financial entity shall have a sound, comprehensive and documented ICT risk management framework, integrated into its overall risk management. See Regulation (EU) 2022/2554, Article 6."
          },
          "mapping": {
            "principles": ["P2"],
            "fiches": ["ACF-03", "ACF-12"],
            "operational_note": {
              "fr": "ACF-03/ACF-12 fournissent la composante « risque agentique » du cadre TIC ; P2 calibre l'intensité du contrôle.",
              "en": "ACF-03/ACF-12 provide the 'agentic risk' component of the ICT framework; P2 calibrates control intensity."
            }
          },
          "source": "Regulation (EU) 2022/2554, Article 6",
          "applicable_date": "2025-01-17"
        },
        "11": {
          "title": {
            "fr": "Réponse et rétablissement (continuité TIC)",
            "en": "Response and recovery (ICT business continuity)"
          },
          "text": {
            "fr": "L'entité met en place une politique de continuité d'activité TIC et des plans de réponse et de rétablissement testés régulièrement. Cf. Règlement (UE) 2022/2554, art. 11.",
            "en": "The entity shall put in place an ICT business continuity policy and response and recovery plans, tested regularly. See Regulation (EU) 2022/2554, Article 11."
          },
          "mapping": {
            "principles": ["P3"],
            "fiches": ["ACF-07", "ACF-P7"],
            "operational_note": {
              "fr": "Le kill switch (ACF-07) et les drills de reprise (ACF-P7) sont la déclinaison agentique des plans de réponse/rétablissement.",
              "en": "The kill switch (ACF-07) and takeover drills (ACF-P7) are the agentic instantiation of response/recovery plans."
            }
          },
          "source": "Regulation (EU) 2022/2554, Article 11",
          "applicable_date": "2025-01-17"
        },
        "17": {
          "title": {
            "fr": "Processus de gestion des incidents liés aux TIC",
            "en": "ICT-related incident management process"
          },
          "text": {
            "fr": "L'entité définit, établit et met en œuvre un processus de gestion des incidents TIC pour détecter, gérer et notifier les incidents. Cf. Règlement (UE) 2022/2554, art. 17.",
            "en": "The entity shall define, establish and implement an ICT-related incident management process to detect, manage and notify incidents. See Regulation (EU) 2022/2554, Article 17."
          },
          "mapping": {
            "principles": ["P4"],
            "fiches": ["ACF-09"],
            "operational_note": {
              "fr": "Le registre des décisions (ACF-09) et la piste d'audit (ACF-09) fournissent les éléments de détection et de notification d'incident agentique.",
              "en": "The decision register (ACF-09) and audit trail (ACF-09) provide the agentic-incident detection and notification evidence."
            }
          },
          "source": "Regulation (EU) 2022/2554, Article 17",
          "applicable_date": "2025-01-17"
        },
        "28": {
          "title": {
            "fr": "Gestion du risque lié aux prestataires tiers de services TIC",
            "en": "Management of ICT third-party risk"
          },
          "text": {
            "fr": "L'entité gère le risque lié aux prestataires tiers de services TIC dans le cadre de sa gestion du risque TIC, avec des dispositions contractuelles clés. Cf. Règlement (UE) 2022/2554, art. 28.",
            "en": "The entity shall manage ICT third-party risk as part of its ICT risk management, with key contractual provisions. See Regulation (EU) 2022/2554, Article 28."
          },
          "mapping": {
            "principles": ["P1", "P2"],
            "fiches": ["ACF-P10"],
            "operational_note": {
              "fr": "Lorsque l'agent s'appuie sur un modèle ou service tiers, ACF-P10 documente la dépendance et la responsabilité résiduelle (P1).",
              "en": "Where the agent relies on a third-party model or service, ACF-P10 documents the dependency and residual accountability (P1)."
            }
          },
          "source": "Regulation (EU) 2022/2554, Article 28",
          "applicable_date": "2025-01-17"
        }
      }
    },
    "nis2": {
      "label": {
        "fr": "NIS2 : Directive (UE) 2022/2555 (transposition nationale ; échéance 2024-10-17)",
        "en": "NIS2: Directive (EU) 2022/2555 (national transposition; deadline 2024-10-17)"
      },
      "articles": {
        "20": {
          "title": {
            "fr": "Gouvernance : responsabilité des organes de direction",
            "en": "Governance: management bodies' responsibility"
          },
          "text": {
            "fr": "Les organes de direction des entités essentielles et importantes approuvent les mesures de gestion des risques de cybersécurité, en supervisent la mise en œuvre et suivent une formation. Cf. Directive (UE) 2022/2555, art. 20 (telle que transposée).",
            "en": "Management bodies of essential and important entities shall approve cybersecurity risk-management measures, oversee their implementation, and follow training. See Directive (EU) 2022/2555, Article 20 (as transposed)."
          },
          "mapping": {
            "principles": ["P1"],
            "fiches": ["ACF-01", "ACF-13"],
            "operational_note": {
              "fr": "Aligne avec P1 : responsabilité explicite des dirigeants ; ACF-13 (mandat) trace l'approbation et la supervision côté agents.",
              "en": "Aligns with P1: explicit management accountability; ACF-13 (mandate) records approval and oversight on the agent side."
            }
          },
          "source": "Directive (EU) 2022/2555, Article 20 (as transposed into national law)"
        },
        "21": {
          "title": {
            "fr": "Mesures de gestion des risques de cybersécurité",
            "en": "Cybersecurity risk-management measures"
          },
          "text": {
            "fr": "Les entités prennent des mesures techniques, opérationnelles et organisationnelles appropriées et proportionnées pour gérer les risques pesant sur leurs réseaux et systèmes d'information (approche tous risques). Cf. Directive (UE) 2022/2555, art. 21.",
            "en": "Entities shall take appropriate and proportionate technical, operational and organisational measures to manage risks to their network and information systems (all-hazards approach). See Directive (EU) 2022/2555, Article 21."
          },
          "mapping": {
            "principles": ["P2"],
            "fiches": ["ACF-03", "ACF-12"],
            "operational_note": {
              "fr": "P2 (proportionnalité) fait écho au critère « approprié et proportionné » ; ACF-03/ACF-12 dimensionnent les mesures selon la criticité de l'agent.",
              "en": "P2 (proportionality) echoes the 'appropriate and proportionate' test; ACF-03/ACF-12 size the measures to the agent's criticality."
            }
          },
          "source": "Directive (EU) 2022/2555, Article 21"
        },
        "23": {
          "title": {
            "fr": "Obligations de notification d'incidents",
            "en": "Incident reporting obligations"
          },
          "text": {
            "fr": "Les entités notifient sans retard injustifié les incidents importants à leur CSIRT/autorité compétente (alerte précoce, notification, rapport final) selon les délais prévus. Cf. Directive (UE) 2022/2555, art. 23.",
            "en": "Entities shall notify significant incidents to their CSIRT/competent authority without undue delay (early warning, notification, final report) within the set deadlines. See Directive (EU) 2022/2555, Article 23."
          },
          "mapping": {
            "principles": ["P4"],
            "fiches": ["ACF-09"],
            "operational_note": {
              "fr": "La piste d'audit reconstituable (P4, ACF-09/ACF-09) fournit la matière factuelle des notifications d'incident dans les délais.",
              "en": "The reconstructible audit trail (P4, ACF-09/ACF-09) supplies the factual basis for timely incident notifications."
            }
          },
          "source": "Directive (EU) 2022/2555, Article 23"
        }
      }
    },
    "iso-42001": {
      "label": {
        "fr": "ISO/IEC 42001:2023 : Système de management de l'IA (SMIA)",
        "en": "ISO/IEC 42001:2023: AI management system (AIMS)"
      },
      "articles": {
        "6": {
          "title": {
            "fr": "Planification : risques, opportunités et évaluation d'impact IA",
            "en": "Planning: risks, opportunities and AI impact assessment"
          },
          "text": {
            "fr": "L'organisation planifie le SMIA en traitant les risques et opportunités, en réalisant des évaluations de risque IA et des évaluations d'impact du système d'IA, et en fixant des objectifs. Cf. ISO/IEC 42001:2023, clause 6.",
            "en": "The organisation shall plan the AIMS by addressing risks and opportunities, conducting AI risk assessments and AI system impact assessments, and setting objectives. See ISO/IEC 42001:2023, clause 6."
          },
          "mapping": {
            "principles": ["P2"],
            "fiches": ["ACF-03", "ACF-12"],
            "operational_note": {
              "fr": "ACF-03 (criticité) + ACF-12 (risque) constituent l'évaluation de risque/impact IA exigée par la clause 6.",
              "en": "ACF-03 (criticality) + ACF-12 (risk) constitute the AI risk/impact assessment required by clause 6."
            }
          },
          "source": "ISO/IEC 42001:2023, clause 6"
        },
        "8": {
          "title": {
            "fr": "Fonctionnement (maîtrise opérationnelle)",
            "en": "Operation (operational controls)"
          },
          "text": {
            "fr": "L'organisation planifie, met en œuvre et maîtrise les processus nécessaires pour satisfaire aux exigences et mettre en œuvre les mesures de traitement, y compris la maîtrise des changements. Cf. ISO/IEC 42001:2023, clause 8.",
            "en": "The organisation shall plan, implement and control the processes needed to meet requirements and implement treatment actions, including change control. See ISO/IEC 42001:2023, clause 8."
          },
          "mapping": {
            "principles": ["P3"],
            "fiches": ["ACF-07", "ACF-13"],
            "operational_note": {
              "fr": "La maîtrise opérationnelle de la clause 8 se traduit, pour un agent, par le mandat (ACF-13) et le kill switch (ACF-07).",
              "en": "Clause 8 operational control maps, for an agent, to the mandate (ACF-13) and the kill switch (ACF-07)."
            }
          },
          "source": "ISO/IEC 42001:2023, clause 8"
        },
        "9": {
          "title": {
            "fr": "Évaluation des performances",
            "en": "Performance evaluation"
          },
          "text": {
            "fr": "L'organisation surveille, mesure, analyse et évalue le SMIA, réalise des audits internes et procède à une revue de direction. Cf. ISO/IEC 42001:2023, clause 9.",
            "en": "The organisation shall monitor, measure, analyse and evaluate the AIMS, conduct internal audits and a management review. See ISO/IEC 42001:2023, clause 9."
          },
          "mapping": {
            "principles": ["P4"],
            "fiches": ["ACF-09", "ACF-10"],
            "operational_note": {
              "fr": "L'audit interne et la revue de la clause 9 s'appuient sur la piste d'audit (ACF-09) et la boucle d'amélioration (ACF-10).",
              "en": "The clause 9 internal audit and review draw on the audit trail (ACF-09) and the improvement loop (ACF-10)."
            }
          },
          "source": "ISO/IEC 42001:2023, clause 9"
        },
        "A": {
          "title": {
            "fr": "Annexe A : mesures de référence (contrôles)",
            "en": "Annex A: reference controls"
          },
          "text": {
            "fr": "L'Annexe A fournit un ensemble de mesures de référence (objectifs et contrôles) relatives à la gouvernance, aux ressources, au cycle de vie du système d'IA, aux données et aux parties intéressées. Cf. ISO/IEC 42001:2023, Annexe A.",
            "en": "Annex A provides a set of reference controls (objectives and controls) covering governance, resources, AI system lifecycle, data and interested parties. See ISO/IEC 42001:2023, Annex A."
          },
          "mapping": {
            "principles": ["P1", "P2"],
            "fiches": ["ACF-13", "ACF-P10"],
            "operational_note": {
              "fr": "ACF fournit une déclinaison opérationnelle agentique des contrôles d'Annexe A (rôles DDAO, mandat, traçabilité).",
              "en": "ACF provides an agentic operational instantiation of Annex A controls (DDAO roles, mandate, traceability)."
            }
          },
          "source": "ISO/IEC 42001:2023, Annex A"
        }
      }
    }
  }
}

